function fmtCurrency(val: number): string {
  if (val >= 1_000_000) return `${(val / 1_000_000).toFixed(1)}M DZD`;
  if (val >= 1_000) return `${(val / 1_000).toFixed(0)}K DZD`;
  return `${val.toLocaleString()} DZD`;
}

