// ── Helpers ──────────────────────────────────────────────────────────────────

function formatCurrencyDZD(value: number): string {
  if (value >= 1_000_000) {
    return `${(value / 1_000_000).toFixed(1)}M`;
  }
  if (value >= 1_000) {
    return `${(value / 1_000).toFixed(0)}K`;
  }
  return value.toLocaleString("fr-DZ");
}

function getRiskColor(score: number): {
  bg: string;
  text: string;
  bar: string;
  label: string;
} {
  if (score > 0.7) {
    return {
      bg: "bg-red-500/15",
      text: "text-red-700 dark:text-red-400",
      bar: "bg-red-500",
      label: "Élevé",
    };
  }
  if (score >= 0.4) {
    return {
      bg: "bg-amber-500/15",
      text: "text-amber-700 dark:text-amber-400",
      bar: "bg-amber-500",
      label: "Moyen",
    };
  }
  return {
    bg: "bg-emerald-500/15",
    text: "text-emerald-700 dark:text-emerald-400",
    bar: "bg-emerald-500",
    label: "Faible",
  };
}

function getSupplierStatusStyle(status: string): {
  className: string;
  label: string;
} {
  switch (status) {
    case "high_risk":
    case "critical":
      return {
        className:
          "bg-red-500/15 text-red-700 border-red-500/30 dark:text-red-400",
        label: status === "critical" ? "Critique" : "Élevé",
      };
    case "medium_risk":
      return {
        className:
          "bg-amber-500/15 text-amber-700 border-amber-500/30 dark:text-amber-400",
        label: "Moyen",
      };
    case "low_risk":
    default:
      return {
        className:
          "bg-emerald-500/15 text-emerald-700 border-emerald-500/30 dark:text-emerald-400",
        label: "Faible",
      };
  }
}

