// ── Main Component ───────────────────────────────────────────────────────────

export default function PredictionsView() {
  const [churnData, setChurnData] = useState<ChurnData | null>(null);
  const [supplyData, setSupplyData] = useState<SupplyRiskData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("churn");

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [churnRaw, supplyRaw] = await Promise.all([
        fetch("/api/predictions/churn?limit=50").then((r) => r.json()),
        fetch("/api/predictions/supply-risk").then((r) => r.json()),
      ]);

      // ── Churn Data ──────────────────────────────────────────
      const predictions = churnRaw.predictions || [];
      const churnTransformed: ChurnData = {
        atRiskCustomers: predictions.map((p: any) => ({
          customerId: p.id,
          name: p.name ?? "",
          sector: p.sector ?? "",
          region: p.region ?? "",
          churnRisk: (p.computedRiskScore ?? 0) / 100,
          totalRevenue: p.totalRevenue ?? 0,
          daysSinceLastOrder: p.daysSinceLastOrder ?? 0,
          lifetimeValue: p.lifetimeValue ?? 0,
          riskFactors: p.riskFactors ?? [],
        })),
        summary: {
          totalAtRisk: (churnRaw.highRiskCount ?? 0) + (churnRaw.mediumRiskCount ?? 0),
          highRisk: churnRaw.highRiskCount ?? 0,
          mediumRisk: churnRaw.mediumRiskCount ?? 0,
          avgChurnRisk: predictions.length > 0
            ? predictions.reduce((sum: number, p: any) => sum + (p.computedRiskScore ?? 0) / 100, 0) / predictions.length
            : 0,
        },
      };

      // ── Supply Data ─────────────────────────────────────────
      const suppliers = supplyRaw.suppliers || [];
      const riskMatrix = supplyRaw.riskMatrix || {};
      const supplyTransformed: SupplyRiskData = {
        supplierRisks: suppliers.map((s: any) => ({
          supplierId: s.supplierId ?? "",
          delayRate: 1 - (s.onTimeRate ?? 0),
          avgQualityScore: s.avgQualityScore ?? 0,
          avgLeadTime: s.avgLeadTimeDays ?? 0,
          riskScore: (s.riskScore ?? 0) / 100,
          status: s.riskLevel === "critical" ? "critical" : s.riskLevel === "high" ? "high_risk" : s.riskLevel === "medium" ? "medium_risk" : "low_risk",
        })),
        summary: {
          totalSuppliers: supplyRaw.totalSuppliers ?? 0,
          highRisk: (riskMatrix.critical ?? 0) + (riskMatrix.high ?? 0),
          mediumRisk: riskMatrix.medium ?? 0,
          lowRisk: riskMatrix.low ?? 0,
          avgDelayRate: suppliers.length > 0
            ? suppliers.reduce((sum: number, s: any) => sum + (1 - (s.onTimeRate ?? 0)), 0) / suppliers.length
            : 0,
        },
      };

      setChurnData(churnTransformed);
      setSupplyData(supplyTransformed);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erreur fatale");
      toast.error("Erreur de synchronisation IA");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <PredictionsSkeleton />;
  if (error) {
    return (
      <div className="text-center py-8 text-destructive">
        <p className="font-medium">{error}</p>
        <Button variant="outline" className="mt-4 rounded-xl" onClick={() => { setError(null); fetchData(); }}>Réessayer</Button>
      </div>
    );
  }
  if (!churnData && !supplyData) return <EmptyState />;

  const totalCritical = (churnData?.summary.highRisk ?? 0) + (supplyData?.summary.highRisk ?? 0);

  return (
    <div className="space-y-6">
      {/* ── Risk Header ──────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 animate-fade-in translate-y-[-4px]">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-premium-gradient">Prédictions & Analyse de Risques</h1>
          <p className="text-sm text-muted-foreground">Analyses automatisées par IA sur les segments critiques.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end -space-y-0.5">
            <span className="text-[10px] font-bold uppercase text-red-500 tracking-wider">Alerte IA Critique</span>
            <span className="text-lg font-bold tabular-nums">
              {totalCritical} Événements
            </span>
          </div>
          <Button 
            variant="outline" 
            size="icon" 
            className="rounded-xl h-10 w-10 bg-card/50"
            onClick={fetchData}
          >
            <RefreshCw className={cn("w-4 h-4", loading && "animate-spin")} />
          </Button>
        </div>
      </div>

      {/* ── Tabs ────────────────────────────────────────────────────── */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
        <div className="flex items-center justify-between mb-4">
          <TabsList className="bg-card/40 p-1 rounded-xl border border-border/40">
            <TabsTrigger 
              value="churn" 
              className="rounded-lg gap-2 text-xs font-bold uppercase transition-all data-[state=active]:bg-primary data-[state=active]:text-primary-foreground"
            >
              <Users className="w-4 h-4" />
              Fidélisation
            </TabsTrigger>
            <TabsTrigger 
              value="supply" 
              className="rounded-lg gap-2 text-xs font-bold uppercase transition-all data-[state=active]:bg-primary data-[state=active]:text-primary-foreground"
            >
              <Truck className="w-4 h-4" />
              Chaîne Logistique
            </TabsTrigger>
          </TabsList>

          <div className="hidden md:flex items-center gap-2 bg-emerald-500/5 px-3 py-1.5 rounded-xl border border-emerald-500/10 shadow-sm">
            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
            <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-tight">Moteur IA actif</span>
          </div>
        </div>

        <TabsContent value="churn" className="animate-scale-in outline-none">
          {churnData ? <CustomerChurnTab churnData={churnData} /> : <EmptyState />}
        </TabsContent>

        <TabsContent value="supply" className="animate-scale-in outline-none">
          {supplyData ? <SupplyChainTab supplyData={supplyData} /> : <EmptyState />}
        </TabsContent>
      </Tabs>
    </div>
  );
}
